function [c] = mag_counts(b, s)
%MAG_COUNTS  The magnetometer's field b (body) as its registers' counts.
%   b: real[T][3] (passed in kg/(s^2 A))
%   s: EmuScale (passed rec)
%   returns c: int[3] (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    c = zeros(3, 1);
    c = zeros(3, 1);
    for i = (0):((3) - 1)
        c((i) + 1) = asils.models.emucodec.emu_count((b((i) + 1) / s.mag), s.lo16, s.hi16);
    end
end
